import{z as s,x as i,o as A,c as l,q as t,j as r,D as a,d as B,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"协作与复现收束","description":"","frontmatter":{"title":"协作与复现收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc2-map.md","filePath":"quant/rc2-map.md","lastUpdated":1791413859000}'),F={name:"quant/rc2-map.md"};function p(d,E,C,D,c,m){const e=i("Mermaid");return A(),l("div",null,[E[2]||(E[2]=t('<h1 id="协作与复现收束" tabindex="-1">协作与复现收束 <a class="header-anchor" href="#协作与复现收束" aria-label="Permalink to &quot;协作与复现收束&quot;">​</a></h1><div class="epigraph"><p>复现是协作的最小单元：不能重跑的实验无法被评审，无法被评审的研究无法协作。</p><footer>—— 据 Arnott, Harvey and Markowitz, A Backtesting Protocol in the Era of Machine Learning, Journal of Financial Data Science, 2019 与 Wilson et al., Best Practices for Scientific Computing, 2014 全课程口径整理</footer></div><p><a href="/quant/rc2-cross-team-cases">上一课</a>用三个案例把接口写成契约。十课走完，本课收束：先收回个人层四课，再收回组织层五课，最后把这条线放回它与回测框架设计课程的接缝上。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束课要回答的问题只有一个：这十课合起来，把研究这件事改成了什么。## 方法</p><p>答案写在两个层的分工里。个人层改的是<strong>一次研究</strong>：规范钉显式性，notebook 钉重启重跑，实验管理钉 \\(N\\) 的完整性，复现包钉陌生人盲跑——四课合起来，把一次实验从「做过的动作」变成可复述的函数 \\(f(\\text{配置}, \\text{快照}) \\to \\text{结果}\\)。组织层改的是<strong>一群人的研究</strong>：评审摊开接缝盲区，文档接住论证与死因，知识库抵抗失忆并标记失效，委员会把停止的权力独立于人，跨团队契约把「我知道」变成「引用版本」。两层不是并列的清单，是依赖关系：组织层审的全部材料——diff、指纹、台账、一页文档、复现包——都是个人层的产物；个人层不达标，组织层就在空转。</p>',6)),(A(),r(o,null,{default:a(()=>[n(e,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E8%A7%84%E8%8C%83%EF%BC%9A%E6%98%BE%E5%BC%8F%E6%80%A7%22%5D%20--%3E%20P2%5B%22notebook%EF%BC%9A%E9%87%8D%E5%90%AF%E9%87%8D%E8%B7%91%22%5D%0A%20%20P2%20--%3E%20P3%5B%22%E5%AE%9E%E9%AA%8C%E7%AE%A1%E7%90%86%EF%BC%9AN%20%E5%AE%8C%E6%95%B4%22%5D%0A%20%20P3%20--%3E%20P4%5B%22%E5%A4%8D%E7%8E%B0%E5%8C%85%EF%BC%9A%E7%9B%B2%E8%B7%91%E9%80%9A%E8%BF%87%22%5D%0A%20%20P4%20--%3E%20O1%5B%22%E8%AF%84%E5%AE%A1%EF%BC%9A%E6%91%8A%E5%BC%80%E6%8E%A5%E7%BC%9D%22%5D%0A%20%20O1%20--%3E%20O2%5B%22%E6%96%87%E6%A1%A3%EF%BC%9A%E8%AE%BA%E8%AF%81%E4%B8%8E%E6%AD%BB%E5%9B%A0%22%5D%0A%20%20O2%20--%3E%20O3%5B%22%E7%9F%A5%E8%AF%86%E5%BA%93%EF%BC%9A%E5%A4%B1%E6%95%88%E6%A0%87%E8%AE%B0%22%5D%0A%20%20O3%20--%3E%20O4%5B%22%E5%A7%94%E5%91%98%E4%BC%9A%EF%BC%9A%E5%88%A4%E6%8D%AE%E8%A3%81%E5%86%B3%22%5D%0A%20%20O4%20--%3E%20O5%5B%22%E5%A5%91%E7%BA%A6%EF%BC%9A%E8%B7%A8%E5%9B%A2%E9%98%9F%E7%89%88%E6%9C%AC%22%5D%0A%20%20P4%20--%3E%20Q%5B%22%E5%8F%AF%E9%87%8D%E6%94%BE%E5%8F%AF%E8%AE%A1%E6%95%B0%22%5D%0A%20%20O5%20--%3E%20R%5B%22%E5%8F%AF%E8%AF%84%E5%AE%A1%E5%8F%AF%E8%A3%81%22%5D%0A%20%20Q%20--%3E%20R%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>全课程反复出现的机制只有三个。<strong>显式</strong>：凡是重跑与裁决所需的东西——参数、种子、依赖、判据、放弃线——先于结果存在并落进文件；隐含是所有事故的共同入口。<strong>可数</strong>：试验入账、\\(N\\) 完整、决策按时间记录，多重检验折价才有分母——<a href="/quant/research-log-discipline">研究日志纪律</a>的 t 值门槛与<a href="/quant/bailey-dsr">缩水夏普</a>都建立在这个分母上。<strong>挂判据</strong>：放弃落死因、驳回落条款、复盘落接口，所有「不做了」「不许过」都有可检索、可推翻的落点——这是<a href="/quant/research-postmortem">研究复盘</a>「『效果不好』不是数据」在全课程的重现。</p><p>与回测框架设计课程的接缝值得明写：那门课把回测语义做成可维护、可审计、可重放的<strong>软件</strong>——引擎重放事件流；本课程把研究过程做成可重放的<strong>组织记忆</strong>——台账重放决策、快照重放输入、文档重放论证。两门课合起来，研究才同时拥有两种可重放：计算的与决定的。缺前者，结论无从核查；缺后者，核查过的结论也无从问责。</p>',3)),(A(),r(o,null,{default:a(()=>[n(e,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%A4%8D%E7%9B%98%EF%BC%9A%E8%BF%99%E4%B8%AA%E7%BB%93%E8%AE%BA%E4%B8%BA%E4%BD%95%E4%B8%8D%E5%8F%AF%E4%BF%A1%22%5D%20--%3E%20B%7B%22%E9%87%8D%E8%B7%91%E6%89%80%E9%9C%80%E4%B9%8B%E7%89%A9%E6%98%AF%E5%90%A6%E6%98%BE%E5%BC%8F%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20C%5B%22%E9%9A%90%E5%90%AB%E6%94%B9%E9%A2%98%EF%BC%9A%E8%B7%AF%E5%BE%84%20%E7%A7%8D%E5%AD%90%20%E4%BE%9D%E8%B5%96%22%5D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20D%7B%22%E5%B0%9D%E8%AF%95%E6%AC%A1%E6%95%B0%20N%20%E5%AE%8C%E6%95%B4%E5%85%A5%E8%B4%A6%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20E%5B%22%E5%88%86%E6%AF%8D%E7%BC%BA%E5%A4%B1%EF%BC%9A%E8%BF%90%E6%B0%94%E8%A2%AB%E8%AF%BB%E6%88%90%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20F%7B%22%E6%AF%8F%E4%B8%AA%E5%86%B3%E5%AE%9A%E6%98%AF%E5%90%A6%E6%8C%82%E5%88%A4%E6%8D%AE%EF%BC%9F%22%7D%0A%20%20F%20--%3E%7C%22%E5%90%A6%22%7C%20G%5B%22%E5%8F%A3%E5%A4%B4%E5%86%B3%E5%AE%9A%EF%BC%9A%E6%97%A0%E8%90%BD%E7%82%B9%E4%B8%8D%E5%8F%AF%E6%8E%A8%E7%BF%BB%22%5D%0A%20%20F%20--%3E%7C%22%E6%98%AF%22%7C%20H%5B%22%E5%8F%AF%E5%8F%91%E7%8E%B0%20%E5%8F%AF%E5%BD%92%E5%9B%A0%20%E5%8F%AF%E5%A4%8D%E7%9B%98%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p><span class="marginnote">这张图与上图分工不同：上图画十课的依赖顺序，这张画三个机制各自缺了会死在哪——事故复盘时按图索骥。直觉类比：「显式」就是「写进文件」：脑子里的默认值等于没有默认值，会议室里的口头共识等于没有共识，只有落在文件里、带时间戳的东西才能在三个月后出来作证。</span></p><p><span class="marginnote">数字实例看「可数」：某因子在 40 次尝试中最好的一个 \\(t=2.5\\)，按经典门槛 2 算「显著」；按 Harvey–Liu–Zhu 抬到 3 的跨试验门槛，\\(2.5 \\lt 3\\) 只能归入「待定」。同一组数、两个结论——差别只在分母 \\(N=40\\) 有没有躺在台账里。</span></p><p><span class="marginnote">全课程只要求背走一个数：Harvey–Liu–Zhu 之后，跨试验比较的 t 统计量门槛从 2 抬到 3。而它成立的前提只有一个——分母 \\(N\\) 完整地躺在台账里；这一前提就是本课程十课的全部工程。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束课划边界：工具会过期，机制不会。实验跟踪产品、notebook 形态、wiki 与工作流引擎，三年一代；显式、可数、挂判据这三条机制与工具无关，换什么栈都要重实现一遍。课程也不承诺复现能消除错误：它只保证错误<strong>可发现、可归因、可复盘</strong>——泄漏的因子复现得越完美，越依赖评审清单与判据去拦。最后，这套协作有真实成本：评审的延迟、委员会的节奏、契约的维护，都是研究速度的对价；课程各课已给过控制成本的口径——门设在押资源的时刻、契约只留三条硬条款、知识库标灰不删除——照用即可，不必加码。</p><p><span class="marginnote">常见误区：初学者容易以为「上一个实验跟踪平台」就等于完成了实验管理。工具是机制的载体，不是机制本身——平台不会替你阻止「这次先不记」，台账分母照样缺；换栈时显式、可数、挂判据要在新栈里逐条重落地，验收标准是流程行为，不是软件采购合同。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>个人层四课把一次研究变成可复述的函数：显式、可重跑、可计数、可盲跑。</li><li>组织层五课把一群人的研究变成可裁的证据链：评审、文档、知识库、委员会、契约。</li><li>三个贯穿机制：显式（先于结果存在）、可数（\\(N\\) 完整入账）、挂判据（决定可检索可推翻）。</li><li>与回测框架课程合看：引擎重放计算，台账重放决策，研究才同时可核查、可问责。</li><li>工具三年一代，机制不过期；协作的成本照各课给的口径控制，不必加码。</li><li>出处：Arnott, Harvey and Markowitz, <em>JFDS</em>, 2019；Wilson et al., 2014；Harvey, Liu and Zhu, <em>RFS</em>, 2016；站内<a href="/quant/research-log-discipline">研究日志纪律</a>、<a href="/quant/bailey-dsr">缩水夏普</a>、<a href="/quant/research-postmortem">研究复盘</a>与上一课<a href="/quant/rc2-cross-team-cases">跨团队协作与案例</a>。</li></ul>',8))])}const _=s(F,[["render",p]]);export{u as __pageData,_ as default};
